var n={en:`Inspectors fill forms and upload photographs at remote sites with unreliable connectivity. No saved observation may disappear on network loss.`,ua:`Інспектори заповнюють форми й додають фотографії на об’єктах зі слабким зв’язком. Жодне збережене спостереження не повинно зникнути при втраті мережі.`};var r={en:[`Draw local storage, secure credentials, API and sync worker.`,`Define offline IDs, conflict handling and upload resume.`,`Show pending, synced and failed client states.`],ua:[`Намалюй локальне сховище, захищені дані доступу, API й синхронізацію.`,`Визнач офлайн-ID, конфлікти та відновлення передачі.`,`Покажи стани очікування, успіху й помилки.`]};var o=[{en:`Offline edits are durable before network return.`,ua:`Офлайн-зміни надійно зберігаються до появи мережі.`},{en:`Credentials are not stored unprotected in ordinary app data.`,ua:`Секрети не зберігаються відкрито у звичайних даних застосунку.`}];var s={scenario:n,tasks:r,checks:o};export{o as checks,s as default,n as scenario,r as tasks};